-- Generated by build.py from assessments/*.json. Run schema.sql first. Safe to run again: it replaces the questions.

insert into public.assessments (slug, title, pass_pct, questions) values ('as-comparative-advantage', $q$Comparative Advantage: assessment$q$, 80, $q$[{"id": "q1", "type": "num", "q": "Blue can make at most 40 coats or 160 shirts. How many shirts does Blue give up to make 1 coat?", "ans": 4, "tol": 0, "marks": 1, "topic": "Opportunity cost", "hint": "Enter a number.", "ok": "Correct: 160 ÷ 40 = 4 shirts.", "fb": "Divide what is given up (shirts) by what is gained (coats): 160 ÷ 40 = 4. Revisit Step 2 of the worked example in the Learn tab.", "model": "4"}, {"id": "q2", "type": "num", "q": "Red can make at most 120 coats or 240 shirts. How many coats does Red give up to make 1 shirt? (give a decimal)", "ans": 0.5, "tol": 0.01, "marks": 1, "topic": "Opportunity cost", "hint": "Enter a number.", "ok": "Correct: 120 ÷ 240 = 0.5 coat.", "fb": "The opportunity cost of a shirt is the inverse of the coat calculation: coats given up ÷ shirts gained = 120 ÷ 240 = 0.5. Check Step 2 again.", "model": "0.5"}, {"id": "q3", "type": "mcq", "q": "Using the figures above, which country has the comparative advantage in coats?", "opts": ["Red", "Blue", "Both countries", "Neither country"], "ans": "0", "marks": 1, "topic": "Comparative advantage", "ok": "Correct: Red gives up 2 shirts per coat, Blue gives up 4, so Red's opportunity cost is lower.", "fb": "Compare opportunity costs, not total output. Red gives up 2 shirts per coat and Blue gives up 4, so Red is the lower-cost producer of coats. Re-read the table in Step 2.", "model": "Red"}, {"id": "q4", "type": "text", "q": "Complete the definition: a country has a comparative advantage in a good when it can produce it at a lower ________ than another country.", "groups": [["opportunity cost", "opportunity costs"]], "marks": 1, "topic": "Definitions", "ok": "Correct: lower opportunity cost.", "fb": "The definition is about opportunity cost, not about producing more. A country has a comparative advantage when it gives up fewer other goods to make the good. See the Tips & keywords tab.", "model": "opportunity cost", "hint": "Two words."}, {"id": "q5", "type": "mcq", "q": "A country can make every good using fewer resources than its trading partner. Could it still gain from trade?", "opts": ["Yes, because it is likely to have a lower opportunity cost in some goods", "No, because it has nothing to gain from a weaker country", "Only if the other country has an absolute advantage in something", "Only if it imports every good"], "ans": "0", "marks": 1, "topic": "Absolute vs comparative", "ok": "Correct: the gain comes from comparative, not absolute, advantage.", "fb": "Absolute advantage in everything does not stop trade being worthwhile. Gains come from specialising where the opportunity cost is lower. See 'A country can have an absolute advantage in everything and still gain from trade' in the Learn tab.", "model": "Yes, because it is likely to have a lower opportunity cost in some goods"}, {"id": "q6", "type": "mcq", "q": "In the worked example a coat costs Red 2 shirts and Blue 4 shirts to make. Between which rates of exchange could both countries gain?", "opts": ["Under 2 shirts per coat", "Between 2 and 4 shirts per coat", "Over 4 shirts per coat", "Exactly 3 shirts per coat only"], "ans": "1", "marks": 1, "topic": "Terms of trade", "ok": "Correct: Red wants more than 2 shirts per coat, Blue will pay less than 4.", "fb": "Each side must receive a better deal than making the good itself. Red will not sell a coat for under 2 shirts, and Blue will not pay more than 4. Revisit Step 5.", "model": "Between 2 and 4 shirts per coat"}, {"id": "q7", "type": "num", "q": "Red makes only coats (120) and Blue makes only shirts (160). How many shirts does the world produce?", "ans": 160, "tol": 0, "marks": 1, "topic": "Specialisation", "hint": "Enter a number.", "ok": "Correct: only Blue makes shirts, so the world total is 160.", "fb": "After specialising, only Blue makes shirts, so world shirt output is Blue's maximum of 160. See Step 4.", "model": "160"}, {"id": "q8", "type": "num", "q": "At an exchange rate of 3 shirts per coat, Red sells 40 coats. How many shirts does Red receive?", "ans": 120, "tol": 0, "marks": 1, "topic": "Terms of trade", "hint": "Enter a number.", "ok": "Correct: 40 × 3 = 120 shirts.", "fb": "Shirts received = coats sold × shirts per coat = 40 × 3 = 120. See Step 6.", "model": "120"}, {"id": "q9", "type": "mcq", "q": "Which of these is a limitation of a country specialising heavily according to comparative advantage?", "opts": ["It could become over-dependent on a few exports", "World output tends to fall", "Opportunity costs rise to zero", "Consumers have less choice and higher prices"], "ans": "0", "marks": 1, "topic": "Limitations", "ok": "Correct: over-dependence leaves the country exposed to price falls and shocks.", "fb": "Heavy specialisation can leave a country over-dependent on a few exports, so a fall in world prices or demand may hurt it badly. The other options describe the opposite of the theory's benefits. See the Exam questions tab.", "model": "It could become over-dependent on a few exports"}, {"id": "q10", "type": "text", "q": "What name is given to the rate at which one country's goods exchange for another's?", "groups": [["terms of trade"]], "marks": 1, "topic": "Terms of trade", "ok": "Correct.", "fb": "The term is 'terms of trade'. Add it to your keyword list in the Tips & keywords tab.", "model": "The terms of trade."}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('as-elasticities-of-demand', $q$Elasticities of Demand: assessment$q$, 80, $q$[{"id": "q1", "type": "num", "q": "Price rises from $10 to $12 and quantity demanded falls from 1,000 to 900. Calculate PED (ignore the sign, give one decimal).", "ans": 0.5, "tol": 0.05, "marks": 1, "topic": "PED calculation", "hint": "Enter a number.", "ok": "Correct: %ΔP = 20%, %ΔQ = 10%, PED = 10 ÷ 20 = 0.5.", "fb": "Use percentage changes on the original value: %ΔP = 2 ÷ 10 = 20%, %ΔQ = 100 ÷ 1,000 = 10%. PED = 10 ÷ 20 = 0.5. Revisit the PED formula in the Learn tab.", "model": "0.5", "abs": true}, {"id": "q2", "type": "num", "q": "Incomes rise by 5% and demand for a good rises by 15%. Calculate YED.", "ans": 3, "tol": 0.01, "marks": 1, "topic": "YED calculation", "hint": "Enter a number.", "ok": "Correct: 15 ÷ 5 = 3.", "fb": "YED = %ΔQd ÷ %ΔY = 15 ÷ 5 = 3. A figure above 1 suggests a luxury or income-elastic good.", "model": "3"}, {"id": "q3", "type": "num", "q": "The price of good B rises by 10% and demand for good A falls by 25%. Calculate XED, including the sign.", "ans": -2.5, "tol": 0.05, "marks": 1, "topic": "XED calculation", "hint": "Include the minus sign if it is negative.", "ok": "Correct: −25 ÷ 10 = −2.5, which suggests complements.", "fb": "XED = %ΔQd of A ÷ %ΔP of B = −25 ÷ 10 = −2.5. Keep the sign for XED, because it shows whether the goods are substitutes or complements.", "model": "-2.5"}, {"id": "q4", "type": "mcq", "q": "A good has a PED of 0.4. If its price rises, what is likely to happen to total revenue?", "opts": ["It rises", "It falls", "It stays the same", "It cannot be known"], "ans": "0", "marks": 1, "topic": "PED and revenue", "ok": "Correct: demand is inelastic, so quantity falls proportionally less than price rises.", "fb": "With PED below 1 (inelastic), the % fall in quantity is smaller than the % rise in price, so revenue tends to rise. See the revenue table in the Learn tab.", "model": "It rises"}, {"id": "q5", "type": "mcq", "q": "A firm cuts the price of a product with PED = 1.8. What is likely to happen to its revenue?", "opts": ["It rises", "It falls", "No change", "It depends on costs"], "ans": "0", "marks": 1, "topic": "PED and revenue", "ok": "Correct: elastic demand means a price cut tends to raise revenue.", "fb": "PED above 1 (elastic): the % rise in quantity is bigger than the % fall in price, so revenue tends to rise. See Lab 1 in the Explore tab.", "model": "It rises"}, {"id": "q6", "type": "mcq", "q": "A negative YED indicates which type of good?", "opts": ["Luxury good", "Normal necessity", "Inferior good", "Complement"], "ans": "2", "marks": 1, "topic": "YED", "ok": "Correct.", "fb": "A negative income elasticity means demand falls as income rises, which is the definition of an inferior good. Examples include own-brand value ranges.", "model": "Inferior good"}, {"id": "q7", "type": "text", "q": "Complete the definition: PED measures the ________ of quantity demanded to a change in a product's own price.", "groups": [["responsiveness", "responsive", "sensitivity", "sensitive"]], "marks": 1, "topic": "Definitions", "ok": "Correct: responsiveness.", "fb": "PED measures how responsive quantity demanded is to a change in the good's own price. See 'Three elasticities of demand' in the Learn tab.", "model": "Responsiveness.", "hint": "One key term."}, {"id": "q8", "type": "mcq", "q": "Which of these is NOT a usual determinant of the price elasticity of demand?", "opts": ["The availability of substitutes", "The proportion of income spent on the good", "The time period considered", "The firm's cost of production"], "ans": "3", "marks": 1, "topic": "Determinants", "ok": "Correct: costs of production affect supply, not PED.", "fb": "PED depends on demand-side factors such as substitutes, the share of income spent and the time period. A firm's costs affect supply. See 'What determines PED?' in the Learn tab.", "model": "The firm's cost of production"}, {"id": "q9", "type": "text", "q": "The XED between butter and margarine is +1.8. What type of relationship does this show?", "groups": [["substitut*"]], "marks": 1, "topic": "XED", "ok": "Correct: a positive XED suggests substitutes.", "fb": "A positive XED means that when the price of one good rises, demand for the other rises too, which is how substitutes behave. Negative would suggest complements.", "model": "Substitutes."}, {"id": "q10", "type": "mcq", "q": "Along a straight-line demand curve, where is demand most price elastic?", "opts": ["At a high price, low quantity", "At the midpoint", "At a low price, high quantity", "PED is the same everywhere"], "ans": "0", "marks": 1, "topic": "PED along a curve", "ok": "Correct: at high prices, small absolute changes are large percentage changes.", "fb": "The slope is constant but PED is not, because it uses percentages. At the top left a small change in quantity is a large percentage change, so demand is more elastic. Watch the animation in the Watch tab.", "model": "At a high price, low quantity"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('linked-lists', $q$Linked Lists: assessment$q$, 80, $q$[{"id": "q1", "type": "mcq", "q": "What value is normally used as the null pointer at the end of a linked list?", "opts": ["0", "1", "-1", "The length of the list"], "ans": "2", "marks": 1, "topic": "Null pointer", "ok": "Correct: the last node's pointer is -1.", "fb": "The end of the list is marked by a null pointer, which the course uses as -1. Revisit section 01 (The idea).", "model": "-1"}, {"id": "q2", "type": "text", "q": "Complete: heapStartPointer holds the index of the first ________ position in the arrays.", "groups": [["free", "unused", "empty", "available"]], "marks": 1, "topic": "The heap", "ok": "Correct: the first free position.", "fb": "heapStartPointer holds the index of the first free (unused) slot, because the unused positions are kept as a linked list. See section 02 (Anatomy).", "model": "free (unused)", "hint": "One word."}, {"id": "q3", "type": "mcq", "q": "In the array implementation, how many arrays hold the list?", "opts": ["One 2D array", "Two parallel 1D arrays", "Three arrays", "A real memory address list"], "ans": "1", "marks": 1, "topic": "Anatomy", "ok": "Correct: one array for data, one for pointers.", "fb": "Exam questions use two parallel 1D arrays of the same size: one for data, one for the next-pointers. They do not use real memory addresses. See section 02.", "model": "Two parallel 1D arrays"}, {"id": "q4", "type": "num", "q": "Using the arrays shown, what is the third item in the list order? (follow the pointers from startPointer)", "ans": 27, "tol": 0, "marks": 1, "topic": "Tracing", "hint": "Enter a number.", "ok": "Correct: 16, then 19, then 27.", "fb": "Start at index 4 (16), its pointer is 1 so go to index 1 (19), whose pointer is 0, so index 0 (27). The third item is 27. Practise the trace tables in section 03.", "model": "27", "code": "index                  0    1    2    3    4\nmyLinkedList          27   19   36   42   16\nmyLinkedListPointers   2    0    3   -1    1\n\nstartPointer = 4"}, {"id": "q5", "type": "num", "q": "Using the same arrays, at which array index is the item 36 stored?", "ans": 2, "tol": 0, "marks": 1, "topic": "Anatomy", "hint": "Enter a number.", "ok": "Correct: index 2.", "fb": "The data array is [27, 19, 36, 42, 16], so 36 is at index 2. The index where an item is stored is not its position in the list order.", "model": "2", "code": "index                  0    1    2    3    4\nmyLinkedList          27   19   36   42   16\nmyLinkedListPointers   2    0    3   -1    1\n\nstartPointer = 4"}, {"id": "q6", "type": "mcq", "q": "The find function starts its search at which index?", "opts": ["Index 0", "The index in startPointer", "The last index", "heapStartPointer"], "ans": "1", "marks": 1, "topic": "Finding", "ok": "Correct.", "fb": "You do not scan from index 0. Start at startPointer and follow the chain of pointers. See section 03.", "model": "The index in startPointer", "code": "FUNCTION find(itemSearch) RETURNS INTEGER\n  itemPointer <- startPointer\n  found <- FALSE\n  WHILE (itemPointer <> -1) AND NOT found DO\n    IF myLinkedList[itemPointer] = itemSearch THEN\n      found <- TRUE\n    ELSE\n      itemPointer <- myLinkedListPointers[itemPointer]\n    ENDIF\n  ENDWHILE\n  RETURN itemPointer\nENDFUNCTION"}, {"id": "q7", "type": "text", "q": "Look at the code. What value does the function return (the value left in itemPointer) when the item is not in the list?", "groups": [["-1", "minus 1", "null pointer", "nullpointer", "null"]], "marks": 1, "topic": "Finding", "ok": "Correct.", "fb": "The search failing is the outcome, but the function returns a value: when the loop ends without finding the item, itemPointer has followed the chain to the null pointer, -1. The code that called find treats -1 as 'not found'. Trace the loop in section 03.", "model": "-1, the null pointer. The calling code reads -1 as 'not found'.", "hint": "A value, not a sentence.", "code": "FUNCTION find(itemSearch) RETURNS INTEGER\n  itemPointer <- startPointer\n  found <- FALSE\n  WHILE (itemPointer <> -1) AND NOT found DO\n    IF myLinkedList[itemPointer] = itemSearch THEN\n      found <- TRUE\n    ELSE\n      itemPointer <- myLinkedListPointers[itemPointer]\n    ENDIF\n  ENDWHILE\n  RETURN itemPointer\nENDFUNCTION"}, {"id": "q8", "type": "mcq", "q": "When inserting a new node into the middle of a sorted linked list, which of these is NOT needed?", "opts": ["Moving existing data items along the array", "Taking a free slot from the heap", "Changing the previous node's pointer", "Giving the new node a pointer to the next node"], "ans": "0", "marks": 1, "topic": "Inserting", "ok": "Correct: no data ever moves.", "fb": "The point of a linked list is that no data moves. You take a free slot, set the new node's pointer and redirect the previous node's pointer. See section 04.", "model": "Moving existing data items along the array"}, {"id": "q9", "type": "mcq", "q": "Why can inserting into a sorted linked list be quicker than inserting into a sorted array?", "opts": ["Existing items do not have to be shifted along; only pointers change", "The array has to be searched from index 0 every time", "A linked list needs no heap", "Pointers are always faster to read than data"], "ans": "0", "marks": 1, "topic": "Linked list vs array", "ok": "Correct: no data moves.", "fb": "In a sorted array every later item has to be shifted along to make room. In a linked list no data moves and only a couple of pointers are changed. See section 06 (vs. arrays).", "model": "Existing items do not have to be shifted along; only pointers change"}, {"id": "q10", "type": "num", "q": "A linked list is made from arrays of 12 elements and currently holds 5 items. How many nodes are on the heap?", "ans": 7, "tol": 0, "marks": 1, "topic": "The heap", "hint": "Enter a number.", "ok": "Correct: 12 − 5 = 7.", "fb": "Every position not in the list is on the heap (the free list). 12 − 5 = 7. See section 02.", "model": "7"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();
